package com.testforge.testforge_backend.testsuite.repository;
import com.testforge.testforge_backend.domain.Project; import com.testforge.testforge_backend.testsuite.entity.TestSuite; import org.springframework.data.jpa.repository.*; import java.util.*;
public interface TestSuiteRepository extends JpaRepository<TestSuite,Long>{ @Query("select count(item)>0 from TestSuiteScenario item, TestCase tc where item.scenario.id=tc.testScenario.id and tc.id=:testCaseId") boolean containsTestCase(Long testCaseId); @Query("select count(item) from TestSuiteScenario item, TestCase tc where item.scenario.id=tc.testScenario.id and tc.id=:testCaseId") long countMembershipsByTestCaseId(Long testCaseId); @Query("select count(item) from TestSuiteScenario item where item.scenario.id=:scenarioId") long countMembershipsByScenarioId(Long scenarioId); @Query("select count(item) from TestSuiteScenario item where item.scenario.requirement.id=:requirementId") long countMembershipsByRequirementId(Long requirementId); boolean existsByProject(Project p); @Query("select count(item)>0 from TestSuiteScenario item where item.scenario.id=:scenarioId") boolean containsScenario(Long scenarioId); boolean existsByProjectAndNameIgnoreCase(Project p,String n); boolean existsByProjectAndNameIgnoreCaseAndIdNot(Project p,String n,Long id); @EntityGraph(attributePaths={"project","scenarios","scenarios.scenario"}) List<TestSuite> findByProjectOrderByIdAsc(Project p); @EntityGraph(attributePaths="project") List<TestSuite> findByProject_ProjectIdOrderByIdAsc(String projectId); @Override @EntityGraph(attributePaths={"project","scenarios","scenarios.scenario"}) Optional<TestSuite> findById(Long id); }
